var TAB_SYNC_KEYS = {
  "PRESETS & COT": ["mode", "model", "cotEnabled", "thinkEffort", "customThinkEffort", "thinkingV2"],
  "Persona": ["personality", "toggles"],
  "Story Config": ["activeStyleId", "aiRule", "customStyles", "dnRatio", "storyConfig"],
  "Global Toggles & Blocks": ["addons", "blocks", "userLanguage", "userPronouns", "onomatopoeia", "v9Limits"],
  "BLOCKS": ["blockStack", "statBlocks", "blocks"],
  "Story Director": ["storyPlan"],
  "Dynamic Ban List": ["banList", "banListBackend", "banListCustomPromptsEnabled", "banListCustomPrompts"],
  "Image Generation": ["imageGen"],
  "NPCs Bank": ["npcBank"],
  "Memory Core": ["memoryCore"]
};
var TABS_ALREADY_GLOBAL = ["Side Panel", "Global Settings"];
function meguminGlobalSyncMap() {
  if (!extension_settings[extensionName].globalSyncTabs) {
    extension_settings[extensionName].globalSyncTabs = {};
  }
  return extension_settings[extensionName].globalSyncTabs;
}
function meguminIsTabSynced(title) {
  return Boolean(title && meguminGlobalSyncMap()[title]);
}
function applyTabKeysToAllProfiles(title) {
  const keys = TAB_SYNC_KEYS[title];
  if (!keys) return false;
  const liveKey = getCharacterKey() || "default";
  if (_loadedProfileKey && liveKey !== _loadedProfileKey) {
    console.debug(`[Megumin-Suite] Global tab sync declined: the settings on screen belong to "${_loadedProfileKey}" but the active chat is now "${liveKey}". Nothing was broadcast.`);
    return false;
  }
  const currentData = localProfile;
  Object.keys(extension_settings[extensionName].profiles).forEach((profKey) => {
    const prof = extension_settings[extensionName].profiles[profKey];
    keys.forEach((k2) => {
      if (k2 === "storyPlan" && currentData[k2]) {
        if (!prof[k2]) prof[k2] = {};
        const preservedPlan = prof[k2].currentPlan;
        const preservedTracker = prof[k2].lastTrackerState;
        const preservedIndex = prof[k2].planMessageIndex;
        prof[k2] = JSON.parse(JSON.stringify(currentData[k2]));
        prof[k2].currentPlan = preservedPlan || "";
        prof[k2].lastTrackerState = preservedTracker || "";
        prof[k2].planMessageIndex = preservedIndex !== void 0 ? preservedIndex : null;
      } else if (k2 === "npcBank" && currentData[k2]) {
        if (!prof[k2]) prof[k2] = {};
        const preservedNpcs = prof[k2].npcs;
        prof[k2] = JSON.parse(JSON.stringify(currentData[k2]));
        prof[k2].npcs = preservedNpcs || [];
      } else if (k2 === "memoryCore" && currentData[k2]) {
        if (!prof[k2]) prof[k2] = {};
        const preservedShort = prof[k2].shortTermChunks;
        const preservedLong = prof[k2].longTermVault;
        prof[k2] = JSON.parse(JSON.stringify(currentData[k2]));
        prof[k2].shortTermChunks = preservedShort || [];
        prof[k2].longTermVault = preservedLong || [];
      } else if (currentData[k2] !== void 0) {
        prof[k2] = JSON.parse(JSON.stringify(currentData[k2]));
      }
    });
  });
  saveSettingsDebounced();
  return true;
}
function syncPromptsGlobally(moduleName, dataKey, dataValue) {
  const liveKey = getCharacterKey() || "default";
  if (_loadedProfileKey && liveKey !== _loadedProfileKey) {
    console.debug(`[Megumin-Suite] Global prompt sync of ${moduleName}.${dataKey} declined: the value came from "${_loadedProfileKey}" but the active chat is now "${liveKey}". No profiles were changed.`);
    return;
  }
  let valueToStore = dataValue;
  if (dataKey === "customPrompts" || dataKey === "banListCustomPrompts") {
    valueToStore = meguminDiffPrompts(dataValue, moduleName);
  }
  Object.values(extension_settings[extensionName].profiles).forEach((prof) => {
    const clonedValue = valueToStore !== null && typeof valueToStore === "object" ? JSON.parse(JSON.stringify(valueToStore)) : valueToStore;
    if (moduleName === "banList") {
      prof[dataKey] = clonedValue;
    } else {
      if (!prof[moduleName]) return;
      prof[moduleName][dataKey] = clonedValue;
    }
  });
  saveSettingsDebounced();
}

// src/frontend/core/tokens.js
var latestTicket = 0;
async function updateLiveTokenCount() {
  const counterBadge = $2("#ps_live_token_count");
  if (!counterBadge.length) return;
  const ticket = ++latestTicket;
  let counts;
  try {
    counts = await call("tokens:estimate");
  } catch (e2) {
    return;
  }
  if (ticket !== latestTicket) return;
  const { engine = 0, cot = 0, style = 0, addons: addons2 = 0 } = counts || {};
  const total = engine + cot + style + addons2;
  counterBadge.html(`<i class="fa-solid fa-microchip"></i> ~${total}`);
  counterBadge.attr("data-breakdown", `
        <div style="text-align:left; min-width: 160px; font-family: 'Inter', sans-serif;">
            <div style="border-bottom: 1px solid rgba(255,255,255,0.2); padding-bottom: 6px; margin-bottom: 6px; color: var(--gold); font-size: 0.8rem;"><b>Payload Breakdown</b></div>
            <div style="display:flex; justify-content:space-between; font-size: 0.75rem; margin-bottom: 4px;"><span>Engine Core:</span> <span style="color:#10b981; font-weight:bold;">~${engine}</span></div>
            <div style="display:flex; justify-content:space-between; font-size: 0.75rem; margin-bottom: 4px;"><span>CoT / Logic:</span> <span style="color:#3b82f6; font-weight:bold;">~${cot}</span></div>
            <div style="display:flex; justify-content:space-between; font-size: 0.75rem; margin-bottom: 4px;"><span>Style &amp; Config:</span> <span style="color:#a855f7; font-weight:bold;">~${style}</span></div>
            <div style="display:flex; justify-content:space-between; font-size: 0.75rem;"><span>Add-ons/Blocks:</span> <span style="color:#ef4444; font-weight:bold;">~${addons2}</span></div>
        </div>
    `);
  counterBadge.css("cursor", "help");
  counterBadge.css("color", "#10b981");
  setTimeout(() => counterBadge.css("color", "var(--text-muted)"), 400);
}
registerRefreshHook(REFRESH.TOKEN_COUNT, () => {
  void updateLiveTokenCount();
});

// src/shared/utils/regex.js
function escapeRegex(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

